// ServerInterface represents all server handlers.
type ServerInterface interface {
	// List GGUF model files cached on disk (admin only)
	// (GET /api/v1/admin/models)
	ListModels(w http.ResponseWriter, r *http.Request)
	// Read effective runtime config (admin only)
	// (GET /api/v1/admin/runtime-config)
	GetRuntimeConfig(w http.ResponseWriter, r *http.Request)
	// Save runtime config overrides (admin only)
	// (PUT /api/v1/admin/runtime-config)
	PutRuntimeConfig(w http.ResponseWriter, r *http.Request)
	// Restart the llama-server sidecar (admin only)
	// (POST /api/v1/admin/sidecar/restart)
	RestartSidecar(w http.ResponseWriter, r *http.Request)
	// Sidecar process status (admin only)
	// (GET /api/v1/admin/sidecar/status)
	GetSidecarStatus(w http.ResponseWriter, r *http.Request)
	// List all users (admin only)
	// (GET /api/v1/admin/users)
	ListUsers(w http.ResponseWriter, r *http.Request)
	// Invite a new user (admin only)
	// (POST /api/v1/admin/users)
	CreateUser(w http.ResponseWriter, r *http.Request)
	// Delete a user (admin only)
	// (DELETE /api/v1/admin/users/{id})
	DeleteUser(w http.ResponseWriter, r *http.Request, id string)
	// Change role or disabled flag (admin only)
	// (PATCH /api/v1/admin/users/{id})
	UpdateUser(w http.ResponseWriter, r *http.Request, id string)
	// List my API keys (or all keys if admin)
	// (GET /api/v1/api-keys)
	ListApiKeys(w http.ResponseWriter, r *http.Request, params ListApiKeysParams)
	// Issue a new API key
	// (POST /api/v1/api-keys)
	CreateApiKey(w http.ResponseWriter, r *http.Request)
	// Revoke an API key
	// (DELETE /api/v1/api-keys/{id})
	RevokeApiKey(w http.ResponseWriter, r *http.Request, id string)
	// Whether the dashboard needs first-run bootstrap (public)
	// (GET /api/v1/auth/bootstrap-status)
	GetBootstrapStatus(w http.ResponseWriter, r *http.Request)
	// Change the current user's password
	// (POST /api/v1/auth/change-password)
	ChangePassword(w http.ResponseWriter, r *http.Request)
	// Exchange email + password for a session cookie (public)
	// (POST /api/v1/auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// End the current session
	// (POST /api/v1/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// Current authenticated user
	// (GET /api/v1/auth/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// Active sessions of the current user
	// (GET /api/v1/auth/sessions)
	ListMySessions(w http.ResponseWriter, r *http.Request)
	// End one of my sessions (sign out a single device)
	// (DELETE /api/v1/auth/sessions/{id})
	DeleteMySession(w http.ResponseWriter, r *http.Request, id string)
	// Clone + index a GitHub repository outside any specific workspace
	// (POST /api/v1/git-repos)
	AddStandaloneGitRepo(w http.ResponseWriter, r *http.Request)
	// List stored GitHub PATs (metadata only)
	// (GET /api/v1/github-tokens)
	ListGithubTokens(w http.ResponseWriter, r *http.Request)
	// Store a new GitHub PAT (encrypted-at-rest)
	// (POST /api/v1/github-tokens)
	CreateGithubToken(w http.ResponseWriter, r *http.Request)
	// Delete a stored GitHub PAT
	// (DELETE /api/v1/github-tokens/{id})
	DeleteGithubToken(w http.ResponseWriter, r *http.Request, id string)
	// List the GitHub accounts visible to a stored PAT
	// (GET /api/v1/github-tokens/{id}/accounts)
	ListTokenAccounts(w http.ResponseWriter, r *http.Request, id string)
	// List GitHub repositories visible to a stored PAT
	// (GET /api/v1/github-tokens/{id}/repos)
	ListTokenRepos(w http.ResponseWriter, r *http.Request, id string, params ListTokenReposParams)
	// List background jobs (status / type filter)
	// (GET /api/v1/jobs)
	ListJobs(w http.ResponseWriter, r *http.Request, params ListJobsParams)
	// List all registered projects
	// (GET /api/v1/projects)
	ListProjects(w http.ResponseWriter, r *http.Request)
	// Register a new project
	// (POST /api/v1/projects)
	CreateProject(w http.ResponseWriter, r *http.Request)
	// Delete a project and all its indexed data (admin only)
	// (DELETE /api/v1/projects/{path})
	DeleteProject(w http.ResponseWriter, r *http.Request, path ProjectHash)
	// Get one project by hash
	// (GET /api/v1/projects/{path})
	GetProject(w http.ResponseWriter, r *http.Request, path ProjectHash)
	// Patch project settings (admin only)
	// (PATCH /api/v1/projects/{path})
	UpdateProject(w http.ResponseWriter, r *http.Request, path ProjectHash)
	// Open an indexing session
	// (POST /api/v1/projects/{path}/index/begin)
	IndexBegin(w http.ResponseWriter, r *http.Request, path ProjectHash)
	// Cancel any active indexing session (idempotent)
	// (POST /api/v1/projects/{path}/index/cancel)
	IndexCancel(w http.ResponseWriter, r *http.Request, path ProjectHash)
	// Submit a batch of files (max 50)
	// (POST /api/v1/projects/{path}/index/files)
	IndexFiles(w http.ResponseWriter, r *http.Request, path ProjectHash, params IndexFilesParams)
	// Commit the indexing session
	// (POST /api/v1/projects/{path}/index/finish)
	IndexFinish(w http.ResponseWriter, r *http.Request, path ProjectHash)
	// Live progress of the current run, or last completed run
	// (GET /api/v1/projects/{path}/index/status)
	IndexStatus(w http.ResponseWriter, r *http.Request, path ProjectHash)
	// Semantic (vector) search
	// (POST /api/v1/projects/{path}/search)
	SemanticSearch(w http.ResponseWriter, r *http.Request, path ProjectHash)
	// Go-to-definition by symbol name
	// (POST /api/v1/projects/{path}/search/definitions)
	SearchDefinitions(w http.ResponseWriter, r *http.Request, path ProjectHash)
	// File-path substring search
	// (POST /api/v1/projects/{path}/search/files)
	SearchFiles(w http.ResponseWriter, r *http.Request, path ProjectHash)
	// Find references to a symbol
	// (POST /api/v1/projects/{path}/search/references)
	SearchReferences(w http.ResponseWriter, r *http.Request, path ProjectHash)
	// Symbol search by name (prefix/substring)
	// (POST /api/v1/projects/{path}/search/symbols)
	SearchSymbols(w http.ResponseWriter, r *http.Request, path ProjectHash)
	// Project overview (top dirs, recent symbols, totals)
	// (GET /api/v1/projects/{path}/summary)
	GetProjectSummary(w http.ResponseWriter, r *http.Request, path ProjectHash)
	// List workspaces that contain this project
	// (GET /api/v1/projects/{path}/workspaces)
	ListProjectWorkspaces(w http.ResponseWriter, r *http.Request, path ProjectHash)
	// Server / sidecar status (authenticated)
	// (GET /api/v1/status)
	GetStatus(w http.ResponseWriter, r *http.Request)
	// Receive a GitHub webhook delivery (public, HMAC-authenticated)
	// (POST /api/v1/webhooks/github/{repo_id})
	ReceiveGithubWebhook(w http.ResponseWriter, r *http.Request, repoId string, params ReceiveGithubWebhookParams)
	// List all workspaces
	// (GET /api/v1/workspaces)
	ListWorkspaces(w http.ResponseWriter, r *http.Request)
	// Create a new workspace
	// (POST /api/v1/workspaces)
	CreateWorkspace(w http.ResponseWriter, r *http.Request)
	// Delete a workspace
	// (DELETE /api/v1/workspaces/{id})
	DeleteWorkspace(w http.ResponseWriter, r *http.Request, id string)
	// Get a single workspace
	// (GET /api/v1/workspaces/{id})
	GetWorkspace(w http.ResponseWriter, r *http.Request, id string)
	// Update workspace metadata
	// (PATCH /api/v1/workspaces/{id})
	UpdateWorkspace(w http.ResponseWriter, r *http.Request, id string)
	// List repositories attached to a workspace
	// (GET /api/v1/workspaces/{id}/repos)
	ListWorkspaceRepos(w http.ResponseWriter, r *http.Request, id string)
	// Attach a GitHub repository to a workspace
	// (POST /api/v1/workspaces/{id}/repos)
	AddWorkspaceRepo(w http.ResponseWriter, r *http.Request, id string)
	// Attach an already-indexed project to a workspace
	// (POST /api/v1/workspaces/{id}/repos/link)
	LinkExistingProject(w http.ResponseWriter, r *http.Request, id string)
	// Detach a repository from a workspace
	// (DELETE /api/v1/workspaces/{id}/repos/{repo_id})
	DeleteWorkspaceRepo(w http.ResponseWriter, r *http.Request, id string, repoId string)
	// Manually re-trigger the clone + index pipeline
	// (POST /api/v1/workspaces/{id}/repos/{repo_id}/reindex)
	ReindexWorkspaceRepo(w http.ResponseWriter, r *http.Request, id string, repoId string)
	// Get the webhook URL + secret for manual GitHub setup
	// (GET /api/v1/workspaces/{id}/repos/{repo_id}/webhook-info)
	GetWorkspaceRepoWebhookInfo(w http.ResponseWriter, r *http.Request, id string, repoId string)
	// Hybrid BM25+dense search across all repos in a workspace
	// (GET /api/v1/workspaces/{id}/search)
	WorkspaceSearch(w http.ResponseWriter, r *http.Request, id string, params WorkspaceSearchParams)
	// Liveness probe (public)
	// (GET /health)
	GetHealth(w http.ResponseWriter, r *http.Request)
}

